import React, { useState, useRef, useEffect } from 'react';

const CameraProcessor = ({ colorblindType, mode }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);

  useEffect(() => {
    return () => {
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  const applyColorFilter = (ctx, canvas, colorblindType, mode) => {
    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
    const data = imageData.data;
    
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      
      if (mode === 'simulate') {
        if (colorblindType === 'protanopia') {
          data[i] = Math.round(r * 0.567 + g * 0.433);
          data[i + 1] = Math.round(r * 0.558 + g * 0.442);
          data[i + 2] = Math.round(g * 0.242 + b * 0.758);
        } else if (colorblindType === 'deuteranopia') {
          data[i] = Math.round(r * 0.625 + g * 0.375);
          data[i + 1] = Math.round(r * 0.7 + g * 0.3);
          data[i + 2] = Math.round(g * 0.3 + b * 0.7);
        } else if (colorblindType === 'tritanopia') {
          data[i] = Math.round(r * 0.95 + g * 0.05);
          data[i + 1] = Math.round(g * 0.433 + b * 0.567);
          data[i + 2] = Math.round(g * 0.475 + b * 0.525);
        }
      } else if (mode === 'enhance') {
        if (colorblindType === 'protanopia' || colorblindType === 'deuteranopia') {
          data[i + 2] = Math.round(Math.min(255, b * 1.3));
        } else if (colorblindType === 'tritanopia') {
          data[i] = Math.round(Math.min(255, r * 1.3));
        }
      }
    }
    
    ctx.putImageData(imageData, 0, 0);
  };

  const drawFrame = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    
    if (!video || !canvas) return;
    
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    
    if (video.paused || video.ended) {
      return;
    }

    try {
      // Draw video to canvas
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      
      // Apply color filter
      applyColorFilter(ctx, canvas, colorblindType, mode);
    } catch (e) {
      console.error('Draw error:', e);
    }
    
    // Continue animation loop
    animationFrameRef.current = requestAnimationFrame(drawFrame);
  };

  const startCamera = async () => {
    try {
      console.log('Requesting camera...');
      const stream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1280 },
          height: { ideal: 720 }
        },
        audio: false
      });
      
      console.log('Camera access granted');
      streamRef.current = stream;
      
      const video = videoRef.current;
      const canvas = canvasRef.current;
      
      if (!video || !canvas) {
        console.error('Video or canvas element missing');
        return;
      }
      
      video.srcObject = stream;
      video.onloadedmetadata = () => {
        console.log('Video metadata loaded');
        console.log('Video dimensions:', video.videoWidth, 'x', video.videoHeight);
        
        // Set canvas size to match video
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        console.log('Canvas size set to:', canvas.width, 'x', canvas.height);
        
        video.play().then(() => {
          console.log('Video playing');
          setStreaming(true);
          setError(null);
          drawFrame();
        }).catch(err => {
          console.error('Play error:', err);
          setError('Failed to play video: ' + err.message);
        });
      };
      
    } catch (err) {
      console.error('Camera error:', err);
      setError('Camera access error: ' + err.message);
    }
  };

  const stopCamera = () => {
    console.log('Stopping camera');
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setStreaming(false);
  };

  return (
    <div className="component-container">
      <h2>Live Camera Feed</h2>
      
      <div
        className="upload-area"
        style={{ 
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa'
        }}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Ready to start live camera feed</p>
            <p style={{ fontSize: '14px', color: '#666', marginBottom: '20px' }}>
              Click the button below to activate your camera
            </p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>✓ Camera is active</p>
        )}
      </div>

      {error && <div className="error" style={{ marginTop: '15px', padding: '10px' }}>{error}</div>}

      {streaming && (
        <div style={{ marginTop: '20px', textAlign: 'center' }}>
          <video
            ref={videoRef}
            muted={true}
            style={{ display: 'none' }}
          />
          <canvas
            ref={canvasRef}
            style={{ 
              maxWidth: '100%', 
              height: 'auto', 
              border: '2px solid #ddd', 
              borderRadius: '8px',
              backgroundColor: '#000',
              display: 'block',
              margin: '0 auto'
            }}
          />
        </div>
      )}

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button
          className="button"
          onClick={streaming ? stopCamera : startCamera}
        >
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
